div.script:

window.goToLatestVersion = function() {
  const freshTimestamp = Date.now();
  window.location.href = `index.svg?v=${freshTimestamp}`;
};

// Tutorial and Name Logic
window.nextTutStep = function(step) {
  const nameVal = document.getElementById('userNameInput').value.trim();
  if (step === 2) {
    if (!nameVal) {
      alert('Please enter your name!');
      return;
    }
    localStorage.setItem('eagle_user_name', nameVal);
    document.getElementById('tutStep1').style.display = 'none';
    document.getElementById('tutStep2').style.display = 'flex';
    updateGreeting(nameVal);
  }
};

window.finishTutorial = function() {
  document.getElementById('tutorialOverlay').style.display = 'none';
  localStorage.setItem('eagle_tut_done', 'true');
};

function updateGreeting(name) {
  const greetings = [
    `How is it going, ${name}?`,
    `Hey there, ${name}!`,
    `Welcome back, ${name}!`,
    `Ready to play, ${name}?`
  ];
  const randomGreeting = greetings[Math.floor(Math.random() * greetings.length)];
  document.getElementById('heroGreeting').textContent = randomGreeting;
}

window.addEventListener('DOMContentLoaded', () => {
  document.title = "eagle.io";

  // Check First Visit Tutorial
  const tutDone = localStorage.getItem('eagle_tut_done');
  const savedName = localStorage.getItem('eagle_user_name');
  if (!tutDone || !savedName) {
    document.getElementById('tutorialOverlay').style.display = 'flex';
  } else {
    updateGreeting(savedName);
  }

  // Accent Color Theme setup
  const savedAccent = localStorage.getItem('eagle_accent') || '#38bdf8';
  setAccentColor(savedAccent, false);

  window.setAccentColor = function(color, save = true) {
    document.documentElement.style.setProperty('--accent-color', color);
    document.documentElement.style.setProperty('--accent-glow', color + '4d');
    if (save) localStorage.setItem('eagle_accent', color);
  };

  const customAccentPicker = document.getElementById('customAccentPicker');
  const customAccentHex = document.getElementById('customAccentHex');
  customAccentPicker.oninput = (e) => {
    setAccentColor(e.target.value);
    customAccentHex.value = e.target.value;
  };
  customAccentHex.onchange = (e) => {
    setAccentColor(e.target.value);
  };

  // Layout Style Selector
  const layoutStyleSelect = document.getElementById('layoutStyleSelect');
  const savedLayout = localStorage.getItem('eagle_layout') || 'grid';
  layoutStyleSelect.value = savedLayout;
  applyLayout(savedLayout);

  layoutStyleSelect.onchange = (e) => {
    applyLayout(e.target.value);
    localStorage.setItem('eagle_layout', e.target.value);
  };

  function applyLayout(style) {
    const grid = document.getElementById('gamesGrid');
    if (style === 'compact') {
      grid.style.gridTemplateColumns = 'repeat(auto-fit, minmax(220px, 1fr))';
      grid.style.gap = '14px';
    } else {
      grid.style.gridTemplateColumns = 'repeat(auto-fit, minmax(300px, 1fr))';
      grid.style.gap = '24px';
    }
  }

  // Kansas / Central Time Zone Clock
  const clockEl = document.getElementById('liveClock');
  const widgetClock = document.getElementById('widgetClock');
  setInterval(() => {
    const timeStr = new Date().toLocaleTimeString('en-US', {
      timeZone: 'America/Chicago',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    }) + " CT";
    clockEl.textContent = timeStr;
    if (widgetClock) widgetClock.textContent = timeStr;
  }, 1000);

  // Quick Notes Persistence
  const quickNotes = document.getElementById('quickNotes');
  const savedNotes = localStorage.getItem('eagle_notes');
  if (savedNotes) quickNotes.value = savedNotes;
  quickNotes.oninput = (e) => {
    localStorage.setItem('eagle_notes', e.target.value);
  };

  // Apps Dropdown Suite Logic
  const appsDropdownBtn = document.getElementById('appsDropdownBtn');
  const appsDropdown = document.getElementById('appsDropdown');

  appsDropdownBtn.onclick = (e) => {
    e.stopPropagation();
    appsDropdown.classList.toggle('open');
    notifDropdown.classList.remove('open');
  };

  window.openApp = function(appName) {
    appsDropdown.classList.remove('open');
    if (appName === 'latest') goToLatestVersion();
    else if (appName === 'schedule') scheduleModal.classList.add('open');
    else if (appName === 'themes') settingsModal.classList.add('open');
    else if (appName === 'user') {
      document.getElementById('changeNameInput').value = localStorage.getItem('eagle_user_name') || '';
      userSettingsModal.classList.add('open');
    }
    else if (appName === 'updatelog') updateLogModal.classList.add('open');
    else if (appName === 'owner') {
      enteredCode = '';
      codeDisplay.textContent = '____';
      ownerBroadcastPanel.style.display = 'none';
      ownerModal.classList.add('open');
    }
    else if (appName === 'proxy') alert('Proxy Wizard is currently a placeholder.');
    else if (appName === 'bug') bugModal.classList.add('open');
  };

  // Close dropdowns on outside click
  window.addEventListener('click', (e) => {
    if (!appsDropdown.contains(e.target) && e.target !== appsDropdownBtn) {
      appsDropdown.classList.remove('open');
    }
    if (!notifDropdown.contains(e.target) && !notifBtn.contains(e.target)) {
      notifDropdown.classList.remove('open');
    }
  });

  // Notifications Logic
  const notifBtn = document.getElementById('notifBtn');
  const notifBadge = document.getElementById('notifBadge');
  const notifDropdown = document.getElementById('notifDropdown');
  const notifContent = document.getElementById('notifContent');

  notifBtn.onclick = (e) => {
    e.stopPropagation();
    notifDropdown.classList.toggle('open');
    notifBadge.style.display = 'none';
    appsDropdown.classList.remove('open');
  };

  // JSONBin Announcements Sync
  const BIN_URL = "https://api.jsonbin.io/v3/b/6adafef5ac6210605a4b0a6d";
  const MASTER_KEY = "YOUR_MASTER_KEY_HERE";

  async function syncAnnouncement() {
    try {
      const res = await fetch(BIN_URL, { headers: { 'X-Master-Key': MASTER_KEY } });
      const data = await res.json();
      if (data && data.record && data.record.message) {
        notifContent.textContent = data.record.message;
        notifBadge.style.display = 'block';
      }
    } catch (err) {
      console.log('JSONBin sync offline or unconfigured');
    }
  }
  syncAnnouncement();

  // Custom Video Background Uploader and LocalStorage
  const appRoot = document.getElementById('appRoot');
  const bgVideo = document.getElementById('bgVideo');
  const bgVideoInput = document.getElementById('bgVideoInput');
  const clearVideoBtn = document.getElementById('clearVideoBtn');

  const savedVideo = localStorage.getItem('eagle_bg_video');
  if (savedVideo) {
    bgVideo.src = savedVideo;
    bgVideo.style.display = 'block';
    clearVideoBtn.style.display = 'block';
  }

  bgVideoInput.onchange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = function(event) {
        const base64Video = event.target.result;
        localStorage.setItem('eagle_bg_video', base64Video);
        bgVideo.src = base64Video;
        bgVideo.style.display = 'block';
        clearVideoBtn.style.display = 'block';
      };
      reader.readAsDataURL(file);
    }
  };

  clearVideoBtn.onclick = () => {
    localStorage.removeItem('eagle_bg_video');
    bgVideo.pause();
    bgVideo.removeAttribute('src');
    bgVideo.style.display = 'none';
    clearVideoBtn.style.display = 'none';
    bgVideoInput.value = '';
  };

  // Modal Controls
  const updateLogModal = document.getElementById('updateLogModal');
  document.getElementById('closeUpdateLog').onclick = () => updateLogModal.classList.remove('open');

  const scheduleModal = document.getElementById('scheduleModal');
  document.getElementById('closeSchedule').onclick = () => scheduleModal.classList.remove('open');

  const settingsModal = document.getElementById('settingsModal');
  document.getElementById('closeSettingsModal').onclick = () => settingsModal.classList.remove('open');

  const userSettingsModal = document.getElementById('userSettingsModal');
  document.getElementById('closeUserSettings').onclick = () => userSettingsModal.classList.remove('open');

  document.getElementById('saveNameBtn').onclick = () => {
    const newName = document.getElementById('changeNameInput').value.trim();
    if (newName) {
      localStorage.setItem('eagle_user_name', newName);
      updateGreeting(newName);
      userSettingsModal.classList.remove('open');
      alert('Profile name updated successfully!');
    }
  };

  // Schedule Events System
  const eventDateInput = document.getElementById('eventDateInput');
  const eventTitleInput = document.getElementById('eventTitleInput');
  const addEventBtn = document.getElementById('addEventBtn');
  const eventList = document.getElementById('eventList');

  let events = JSON.parse(localStorage.getItem('eagle_events') || '[]');

  function renderEvents() {
    eventList.innerHTML = '';
    if (events.length === 0) {
      eventList.innerHTML = '<div style="color:#94a3b8; font-size:0.85rem;">No upcoming events saved.</div>';
      return;
    }
    events.sort((a,b) => new Date(a.date) - new Date(b.date));
    events.forEach((ev, idx) => {
      const item = document.createElement('div');
      item.style.cssText = 'background:rgba(30,41,59,0.6); padding:8px 12px; border-radius:8px; display:flex; justify-content:space-between; align-items:center; font-size:0.85rem;';
      item.innerHTML = `<span><strong>${ev.date}:</strong> ${ev.title}</span><button onclick="deleteEvent(${idx})" style="background:none; border:none; color:#ef4444; cursor:pointer; font-weight:bold;">✕</button>`;
      eventList.appendChild(item);
    });
  }

  window.deleteEvent = function(idx) {
    events.splice(idx, 1);
    localStorage.setItem('eagle_events', JSON.stringify(events));
    renderEvents();
  };

  addEventBtn.onclick = () => {
    const date = eventDateInput.value;
    const title = eventTitleInput.value.trim();
    if (date && title) {
      events.push({ date, title });
      localStorage.setItem('eagle_events', JSON.stringify(events));
      eventDateInput.value = '';
      eventTitleInput.value = '';
      renderEvents();
    }
  };
  renderEvents();

  // Scroll to Top
  const scrollTopBtn = document.getElementById('scrollTopBtn');
  scrollTopBtn.onclick = () => {
    appRoot.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Custom Symbol Escape Key Setup
  const escKeyInput = document.getElementById('escKeyInput');
  const savedEscKey = localStorage.getItem('eagle_esc_symbol') || ';';
  escKeyInput.value = savedEscKey;

  escKeyInput.oninput = (e) => {
    const val = e.target.value;
    if (/[a-zA-Z0-9\s]/.test(val)) {
      alert('Only symbols allowed for the custom escape key!');
      escKeyInput.value = savedEscKey;
      return;
    }
    if (val) {
      localStorage.setItem('eagle_esc_symbol', val);
    }
  };

  window.addEventListener('keydown', (e) => {
    const currentSymbol = localStorage.getItem('eagle_esc_symbol') || ';';
    if (e.key === currentSymbol) {
      window.location.href = "https://www.google.com";
    }
  });

  // Favorites System and Main Navigation View Modes
  let favorites = JSON.parse(localStorage.getItem('eagle_favorites') || '[]');
  const myHubView = document.getElementById('myHubView');
  const mainNavSelect = document.getElementById('mainNavSelect');

  function updateViewMode() {
    const mode = mainNavSelect.value;
    if (mode === 'hub') {
      myHubView.style.display = 'flex';
      document.querySelectorAll('.game-card').forEach(card => {
        const id = card.getAttribute('data-id');
        if (favorites.includes(id)) card.style.display = 'flex';
        else card.style.display = 'none';
      });
    } else if (mode === 'games') {
      myHubView.style.display = 'none';
      document.querySelectorAll('.game-card').forEach(card => {
        card.style.display = 'flex';
      });
    } else if (mode === 'favorites') {
      myHubView.style.display = 'none';
      document.querySelectorAll('.game-card').forEach(card => {
        const id = card.getAttribute('data-id');
        if (favorites.includes(id)) card.style.display = 'flex';
        else card.style.display = 'none';
      });
    }
  }

  mainNavSelect.onchange = updateViewMode;

  function updateFavUI() {
    document.querySelectorAll('.game-card').forEach(card => {
      const id = card.getAttribute('data-id');
      const star = card.querySelector('.fav-star');
      if (favorites.includes(id)) {
        star.classList.add('active'); star.textContent = '★';
      } else {
        star.classList.remove('active'); star.textContent = '☆';
      }
    });
    updateViewMode();
  }

  window.toggleFavorite = function(id) {
    if (favorites.includes(id)) favorites = favorites.filter(f => f !== id);
    else favorites.push(id);
    localStorage.setItem('eagle_favorites', JSON.stringify(favorites));
    updateFavUI();
  };

  updateFavUI();

  // Owner Keypad Modal
  const ownerModal = document.getElementById('ownerModal');
  const cancelOwner = document.getElementById('cancelOwner');
  const codeDisplay = document.getElementById('codeDisplay');
  const ownerBroadcastPanel = document.getElementById('ownerBroadcastPanel');
  const sendBroadcastBtn = document.getElementById('sendBroadcastBtn');
  const broadcastInput = document.getElementById('broadcastInput');

  let enteredCode = '';
  cancelOwner.onclick = () => ownerModal.classList.remove('open');

  window.pressKey = function(num) {
    if (enteredCode.length < 4) {
      enteredCode += num;
      codeDisplay.textContent = enteredCode.padEnd(4, '_');
      if (enteredCode.length === 4) {
        if (enteredCode === '3166') {
          ownerBroadcastPanel.style.display = 'flex';
        } else {
          alert('Incorrect Code!');
          enteredCode = '';
          codeDisplay.textContent = '____';
        }
      }
    }
  };

  sendBroadcastBtn.onclick = async () => {
    const msg = broadcastInput.value.trim();
    if (msg) {
      try {
        sendBroadcastBtn.textContent = 'Sending...';
        await fetch(BIN_URL, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json', 'X-Master-Key': MASTER_KEY },
          body: JSON.stringify({ message: msg })
        });
        alert('Broadcast notification sent!');
        ownerModal.classList.remove('open');
        syncAnnouncement();
      } catch (e) {
        alert('Broadcast failed.');
      } finally {
        sendBroadcastBtn.textContent = 'Send Notification';
      }
    }
  };

  // Bug Report Modal
  const bugModal = document.getElementById('bugModal');
  document.getElementById('cancelBug').onclick = () => bugModal.classList.remove('open');
  document.getElementById('submitBug').onclick = () => {
    alert('Bug report submitted!');
    bugModal.classList.remove('open');
  };
});
